try {
  const buttons = document.querySelectorAll('button[aria-label="搜索"]');
  if (buttons.length > 0) {
    buttons[0].click();
    return 'clicked';
  }
  return 'not_found';
} catch(e) {
  return 'error: ' + e.message;
}

try {
  const buttons = document.querySelectorAll('button');
  const result = [];
  for (const btn of buttons) {
    const label = btn.getAttribute('aria-label') || btn.textContent;
    if (label && (label.includes('搜索') || label.includes('Search') || label.includes('完成'))) {
      result.push({label: label.trim().substring(0, 100), visible: btn.offsetParent !== null, disabled: btn.disabled});
    }
  }
  return result;
} catch(e) {
  return 'error: ' + e.message;
}

async function clickAndWait() {
  const buttons = document.querySelectorAll('button[aria-label="搜索"]');
  if (buttons.length === 0) return 'no button';
  const btn = buttons[0];
  const initialUrl = window.location.href;
  btn.click();
  await new Promise(r => setTimeout(r, 2000));
  return {initialUrl, finalUrl: window.location.href, changed: window.location.href !== initialUrl};
}
return clickAndWait();

try {
  // Click outside the calendar to close it
  document.body.click();
  // Find all inputs on the page
  const inputs = document.querySelectorAll('input, [role="combobox"]');
  const result = [];
  for (const inp of inputs) {
    const label = inp.getAttribute('aria-label') || inp.getAttribute('placeholder') || '';
    const value = inp.value || '';
    const id = inp.id || '';
    result.push({type: inp.tagName, label: label.substring(0, 100), value: value.substring(0, 80), id, visible: inp.offsetParent !== null});
  }
  return result.slice(0, 30);
} catch(e) {
  return 'error: ' + e.message;
}

async function search() {
  // Find the search button and click it forcefully
  const buttons = document.querySelectorAll('button');
  for (const btn of buttons) {
    const label = btn.getAttribute('aria-label') || '';
    if (label.includes('搜索')) {
      btn.focus();
      btn.click();
      // Dispatch additional click event
      btn.dispatchEvent(new MouseEvent('click', {bubbles: true, cancelable: true}));
      return 'clicked: ' + label;
    }
  }
  return 'not found';
}
return search();
